// The charts the tests lay out: the examples and a stress chart (test/charts, regenerated by
// test/charts/regen.sh and checked by `cargo test`), and the conformance charts.

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { createRequire } from 'node:module'
import type { Ir } from '../src/ir.ts'
import type { ElkLike } from '../src/layout.ts'

const here = path.dirname(fileURLToPath(import.meta.url))
const repo = path.resolve(here, '../../..')

export function chartFiles(): string[] {
  const local = fs
    .readdirSync(path.join(here, 'charts'))
    .filter((f) => f.endsWith('.ir.json'))
    .map((f) => path.join(here, 'charts', f))
  const spec = path.join(repo, 'spec/conformance/charts')
  const conformance = fs
    .readdirSync(spec)
    .filter((f) => f.endsWith('.ir.json'))
    .map((f) => path.join(spec, f))
  return [...local, ...conformance].sort()
}

export function loadIr(file: string): Ir {
  return JSON.parse(fs.readFileSync(file, 'utf8')) as Ir
}

export function chart(name: string): Ir {
  return loadIr(path.join(here, 'charts', `${name}.ir.json`))
}

const require = createRequire(import.meta.url)
const ElkBundled = require('elkjs/lib/elk.bundled.js') as new () => ElkLike

export function newElk(): ElkLike {
  return new ElkBundled()
}
